float r = std::sqrt(1.0f - (2.0f * u.X - 1.0f) * (2.0f * u.X - 1.0f));
float theta = 2.0f * std::numbers::pi_v<float> * u.Y;
float sin_theta = std::sin(theta);
float cos_theta = std::cos(theta);

if (u.X < 0.5f) {
    return Point2f(r * cos_theta, r * sin_theta);
} else {
    return Point2f(-r * cos_theta, -r * sin_theta);
}
